.card.nightMode .idiom { background: #374151; color: #e5e7eb; border-color: #4b5563; }
.card.nightMode .jargon { background: #7f1d1d; color: #fecaca; border-color: #991b1b; }
.card.nightMode .prep { background: #831843; color: #fbcfe8; border-color: #9d174d; }
.card.nightMode .conj { background: #164e63; color: #a5f3fc; border-color: #155e75; }

/* Grammar 관련 */
.card.nightMode .example { background-color: #374151; color: #f1f5f9; border-color: #4b5563; }
.card.nightMode .translation { background-color: #1f2937; color: #9ca3af; border-color: #374151; }
