/* Speaking 관련 */
.card.nightMode .sentence-box { background-color: #374151; color: #f1f5f9; border-color: #4b5563; }
.card.nightMode .speech-text { background: #334155; color: #f1f5f9; border-left-color: #818cf8; }
.card.nightMode .feedback-box { background: #4a044e; color: #f3e8ff; border-left-color: #c084fc; }

/* --- Cloze Blank (앞면 예문 빈칸 스타일) --- */
.example .cloze-blank {
  display: inline-block;
  font-family: -apple-system, "SF Pro Rounded", "SF Mono", Menlo, Consolas, monospace;
  font-weight: 700;
  color: #0071e3;
  letter-spacing: 0.12em;
  padding: 0 2px;
  vertical-align: baseline;
}
.card.nightMode .example .cloze-blank {
  color: #38bdf8;
}


/* --- Example Word Highlight (뒷면 정답 단어 강조) --- */
.example-highlight {
  color: #0071e3;
  font-weight: 700;
  text-decoration: underline;
  text-decoration-color: #0071e3;
  text-underline-offset: 3px;
}
.card.nightMode .example-highlight {
  color: #38bdf8;
  text-decoration-color: #38bdf8;
}

